// `mjs dev` avec `"outputDir": "."` : la garde de la racine du projet refusait aussi les sorties `.json` que le build écrit lui-même
// à la racine du dossier de sortie — `mjs-precache.json` (la liste que le service worker lit) répondait 404, comme les fichiers de
// messages d'un build de production. Une sortie du build se reconnaît à son contenu : empreinte vérifiée, marque `@generated`,
// forme de la liste de pré-cache ; le reste de la règle ne bouge pas

import assert from 'node:assert/strict'
import { mkdirSync, writeFileSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { mjsTmp } from './helpers/tmp.js'
import { StaticServer } from '../src/server/index.js'
import { shortFingerprint } from '../src/bundler/fingerprint.js'

async function statuts(root: string, prefixe: string, chemins: string[]): Promise<Record<string, number>> {
  const srv = new StaticServer({ rootDir: root, pathPrefix: prefixe, port: 0, host: '127.0.0.1', projectRoot: root, configDir: root, config: {} as any })
  await srv.start()
  const vus: Record<string, number> = {}
  try {
    const port = (srv.server!.address() as any).port
    for (const p of chemins) {
      const r = await fetch(`http://127.0.0.1:${port}${prefixe}/${p}`)
      vus[p] = r.status
      await r.text()
    }
  } finally {
    await srv.stop()
  }
  return vus
}

const ecrire = (root: string, p: string, s: string): void => { mkdirSync(dirname(join(root, p)), { recursive: true }); writeFileSync(join(root, p), s) }

describe('mjs dev — sorties du build dans un dossier de sortie à la racine du projet', function () {
  this.timeout(20000)

  it('liste de pré-cache, fichier de messages et feuille marquée servis ; secrets refusés', async () => {
    const root     = mjsTmp('dev-racine-sorties')
    const messages = '{"m":"message"}'
    const err      = 'mjs_err-fr-' + shortFingerprint(messages) + '.json'
    ecrire(root, 'mjs-precache.json', '{"@generated":"ModularJS","version":"x","assets":[]}')
    ecrire(root, err, messages)
    ecrire(root, 'carte.server.css', '/* @generated by ModularJS */\n.carte{}')
    ecrire(root, 'secrets.json', '{"password":"hunter2"}')
    ecrire(root, 'config.json', '{"cle":"secret"}')
    for (const prefixe of ['/modularjs', '']) {
      assert.deepEqual(await statuts(root, prefixe, ['mjs-precache.json', err, 'carte.server.css', 'secrets.json', 'config.json']), {
        'mjs-precache.json': 200, [err]: 200, 'carte.server.css': 200, 'secrets.json': 404, 'config.json': 404,
      }, 'préfixe ' + JSON.stringify(prefixe))
    }
  })

  it('liste de pré-cache sans marque (sortie hors des sources) servie ; un autre contenu sous ce nom refusé', async () => {
    const bon = mjsTmp('dev-racine-precache')
    ecrire(bon, 'mjs-precache.json', '{"version":"a1b2c3d4","assets":["/modularjs/mjs_core-abcde.js"]}')
    assert.deepEqual(await statuts(bon, '', ['mjs-precache.json']), { 'mjs-precache.json': 200 })
    const faux = mjsTmp('dev-racine-faux-precache')
    ecrire(faux, 'mjs-precache.json', '{"version":"x","assets":[],"password":"hunter2"}')
    ecrire(faux, 'carte.json', '/* @generated by ModularJS */ {"password":"hunter2"}')
    assert.deepEqual(await statuts(faux, '', ['mjs-precache.json', 'carte.json']), { 'mjs-precache.json': 404, 'carte.json': 404 })
  })
})
